    {
      "tone": "empático",
      "text": "Entendo a importância, mas estou com a agenda cheia hoje. Fico à disposição em outra oportunidade, certo?",
      "probability": 0.25
    },
    {
      "tone": "direto",
      "text": "Não dá pra hoje. Mas posso sugerir uma alternativa, se quiserem outra data?",
      "probability": 0.2
    },
    {
